const SOURCE = "/** Binary search on the answer: split a (all > 0) into at most k contiguous parts, minimise the largest part sum. */\nexport function segmentsNeeded(a: number[], cap: number): number {\n  let cnt = 1\n  let cur = 0\n  for (const x of a) {\n    if (cur + x > cap) {\n      cnt++\n      cur = x\n    } else cur += x\n  }\n  return cnt\n}\n\n/** segmentsNeeded for each cap in caps (every cap must be >= max(a)). */\nexport function segmentsList(a: number[], caps: number[]): number[] {\n  return caps.map((c) => segmentsNeeded(a, c))\n}\n\nexport function minLargestSum(a: number[], k: number): number {\n  let lo = Math.max(...a)\n  let hi = a.reduce((s, x) => s + x, 0)\n  while (lo < hi) {\n    const mid = lo + Math.floor((hi - lo) / 2)\n    if (segmentsNeeded(a, mid) <= k) {\n      hi = mid\n    } else {\n      lo = mid + 1\n    }\n  }\n  return lo\n}\n"

